mapper.sql:
WHERE 1 = 1

    AND (
      u.email LIKE CONCAT('%', #{keyword}, '%')
      OR u.phone LIKE CONCAT('%', #{keyword}, '%')
      OR u.nickname LIKE CONCAT('%', #{keyword}, '%')
    )


    AND  = #{planCode}


    AND  = #{subscriptionStatus}


    AND CASE
          WHEN  = 'free'
          THEN COALESCE(daily_usage.token_used, 0) >= COALESCE(free_plan.daily_token_limit, 0)
          ELSE COALESCE(monthly_usage.token_used, 0) >= COALESCE(paid_plan.monthly_token_limit, 0)
        END


    AND us.current_period_end >= #{expiresFrom}


    AND us.current_period_end <= #{expiresTo}
